#!/usr/bin/env bash
# M6-T11. Minimum wall and minimum CPU (user+sys) time of N runs (default 3) per binary
# per model, --proof on, under the 4 GB cap. MEASUREMENT ONLY, never a gate. The models
# D-0085 quotes are regenerated by gen.py into a temp dir; a model whose name ends in
# _nl<K> runs under BAGUETTE_NODE_LIMIT=<K> (the deterministic stop, D-0080), since that
# knapsack does not finish.
#   bench/m6t11/timing.sh OLD_MAIN_EXE NEW_MAIN_EXE [N]
set -uo pipefail
: "${BAGUETTE_MEM_CAP_KB:=4000000}"
ulimit -v "${BAGUETTE_MEM_CAP_KB}" 2>/dev/null || true
ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
OLD="$1"; NEW="$2"; N="${3:-3}"
G="$(mktemp -d "${TMPDIR:-/tmp}/m6t11.XXXXXX")"
trap 'rm -rf "${G}"' EXIT
gen() { python3 "${ROOT}/bench/m6t11/gen.py" "$@"; }
gen ne 7 0 > "${G}/ne7.fzn"
gen ne 7 2000 > "${G}/ne7_pad2000.fzn"
gen wide 400 300 400 > "${G}/wide400x300.fzn"
gen knap 8 2 3 1 > "${G}/knap8.fzn"
gen knap 10 2 3 1 > "${G}/knap10.fzn"
gen knap 12 3 3 1 > "${G}/knap12_nl100.fzn"
best() { # bin model -> "min_wall min_cpu" over N runs
  local b="$1" m="$2" nl bw=999999 bc=999999 w c
  nl="$(basename "${m}" .fzn | sed -n 's/.*_nl\([0-9]*\)$/\1/p')"
  for _ in $(seq "${N}"); do
    if [ -n "${nl}" ]; then
      BAGUETTE_NODE_LIMIT="${nl}" /usr/bin/time -o "${G}/t" -f '%e %U %S' "${b}" "${m}" --proof "${G}/run" >/dev/null 2>/dev/null
    else
      /usr/bin/time -o "${G}/t" -f '%e %U %S' "${b}" "${m}" --proof "${G}/run" >/dev/null 2>/dev/null
    fi
    read -r w u s < <(tail -1 "${G}/t")
    c="$(awk -v u="${u}" -v s="${s}" 'BEGIN{print u+s}')"
    bw="$(awk -v a="${w}" -v b="${bw}" 'BEGIN{print (a<b)?a:b}')"
    bc="$(awk -v a="${c}" -v b="${bc}" 'BEGIN{print (a<b)?a:b}')"
  done
  echo "${bw} ${bc}"
}
printf '%-18s %8s %8s %7s   %8s %8s %7s\n' model wall_old wall_new ratio cpu_old cpu_new ratio
for m in "${ROOT}/test/models/width_sat_depth.fzn" "${G}"/*.fzn; do
  read -r ow oc < <(best "${OLD}" "${m}")
  read -r nw nc < <(best "${NEW}" "${m}")
  printf '%-18s %8s %8s %7s   %8s %8s %7s\n' "$(basename "${m}" .fzn)" "${ow}" "${nw}" \
    "$(awk -v o="${ow}" -v n="${nw}" 'BEGIN{ if (n>0) printf "%.2fx", o/n; else print "-" }')" \
    "${oc}" "${nc}" \
    "$(awk -v o="${oc}" -v n="${nc}" 'BEGIN{ if (n>0) printf "%.2fx", o/n; else print "-" }')"
done
